function MarketPulse({ data }) {
  return (
    <section className="stage rounded-xl border border-white/15 bg-black p-6 text-white">
      <header className="mb-5">
        <h1 className="text-4xl font-semibold tracking-tight">Market Pulse</h1>
        <p className="text-sm uppercase text-white/55">Live source</p>
      </header>
      <div className="grid grid-cols-3 gap-3">
        <Metric label="BTC" value={data.btc} detail="usd" />
        <Metric label="ETH" value={data.eth} detail="usd" />
        <LineChart data={data.trend} x="t" y="v" />
      </div>
    </section>
  );
}

const stories = [
  { headline: "Runtime beta opens", source: "Platform", time: "09:00", summary: "Source and permission checks are live" },
  { headline: "Runtime lands", source: "LensUI", time: "09:12", summary: "Depth tokens replaced indentation" },
  { headline: "Streaming tuned", source: "Realtime", time: "09:40", summary: "Live update guardrails are active" }
];
const sources = [
  { label: "Docs", url: "https://example.com", time: "now", note: "Protocol" },
  { label: "Changelog", url: "https://example.com/changelog", time: "5m", note: "Runtime" }
];
function NewsBrief() {
  return (
    <section className="rounded-xl border border-white/15 bg-black p-6 text-white">
      <h1 className="text-4xl font-semibold">Morning Brief</h1>
      <p className="text-white/60">Sourced, compact, skimmable</p>
      <div className="mt-5 grid gap-3">
        {stories.map((story) => <article className="rounded-lg border border-white/10 p-4" key={story.headline}><h2>{story.headline}</h2><span>{story.source}</span><time>{story.time}</time><p>{story.summary}</p></article>)}
      </div>
      <SourceStrip sources={sources} />
    </section>
  );
}

const rows = [
  { label: "LensUI", value: "46 tokens", detail: "Semantic and patchable", tone: "success" },
  { label: "HTML/React", value: "520 tokens", detail: "DOM ceremony and class names", tone: "warning" }
];
function PayloadDecision() {
  return (
    <section className="rounded-xl border border-white/15 bg-black p-6 text-white">
      <h1 className="text-4xl font-semibold">Interface Payloads</h1>
      <p className="text-white/60">Same UI, less noise</p>
      <div className="mt-5 grid grid-cols-2 gap-3">
        {rows.map((row) => (
          <article className={row.tone === "success" ? "border-emerald-400/40 bg-emerald-400/10 p-4" : "border-amber-400/40 bg-amber-400/10 p-4"} key={row.label}>
            <h2>{row.label}</h2><strong>{row.value}</strong><p>{row.detail}</p>
          </article>
        ))}
      </div>
    </section>
  );
}

const trend = [18, 22, 17, 28, 34, 30, 42];
const steps = [
  { label: "Listen", state: "done", detail: "Wake phrase accepted" },
  { label: "Build", state: "active", detail: "Rendering compact UI" },
  { label: "Speak", state: "wait", detail: "Queued" }
];
function AgentStatus() {
  return (
    <section className="rounded-xl border border-white/15 bg-black p-6 text-white">
      <header><h1>Realtime Agent</h1><p>Runtime ops</p></header>
      <div className="grid grid-cols-3 gap-3">
        <Metric label="Latency" value="182ms" detail="p95" />
        <Metric label="Queue" value="72%" detail="ready" tone="success" />
        <Progress value={72} label="session budget" />
      </div>
      <LineChart data={trend} height={150} />
      <Steps items={steps} active="Build" />
    </section>
  );
}
